window.DOSIK=window.DOSIK||{};DOSIK["ad_pubad"]={"1":[{"t":"table","title":"행정이론","head":["이론","내용"],"rows":[["공공선택이론","합리적 선택이론에 제도의 역할을 접목해서 공공부문에까지 확대 적용한다 · 집권적 관료제가 공공서비스를 제공하는데 있어서 유일한 최선의 방안은 아니라고 한다"],["합리적 선택 제도주의","오스트롬(E. Ostrom)은 ‘공유재의 비극’의 해결 방안으로 공동체 중심의 자치제도를 제시한다"],["신제도주의론","공식적 제도나 구조는 물론 비공식적 제도와 규범도 중요하게 강조한다"],["행태주의","가치와 사실문제를 엄격하게 구분하고 자유와 평등의 가치를 연구 대상에서 제외한다 · 1940년대 이후 행정학의 과학화를 위하여 사실판단적인 것만을 연구대상으로 삼았다"],["체제이론","행정현상을 여러 변수 중에서 환경을 포함해 거시적으로 접근한다"],["신행정학","참여와 형평의 가치를 중심으로 현실문제의 처방적 연구를 중시한다 · 관료들이 정책결정을 해야만 한다는 적극적 정치행정일원론을 주장한다"]]},{"t":"flow","title":"행정학 발달","steps":["1887년 윌슨(W. Wilson)은 “행정의 연구(The Study of Administration)”에서 행정의 본질을 관리로 파악하였다","1920년대에서 1930년대에 걸쳐 능률에 기초한 관리를 주장하는 정통 행정학의 모습을 갖추게 되었다","1930년대 이후 등장한 정치행정일원론은 행정의 정책형성 기능을 중시하였다","1940년대 이후 행태주의는 행정학의 과학화를 위하여 사실판단적인 것만을 연구대상으로 삼았다"]}],"2":[{"t":"tree","title":"시장성 테스트","root":"시장성 테스트","branches":[["도입","1990년대의 영국 행정개혁 일환으로 시행되었다"],["성격","특정 공공업무의 처리방식을 선택하기 위한 사전 검증절차이다"],["제공방식","내부시장화 또는 민간화 등 다양한 서비스 제공방식을 제시한다"],["적합한 업무","급속한 시장변화 속에 있는 업무를 포함한다"]]},{"t":"def","term":"뉴거버넌스","text":"정부 내부의 관리보다는 외부 주체와의 관계를 강조한다","ex":["관료는 사회문제를 해결하는 과정에서 협상과 중재 기능을 담당한다"]}],"3":[{"t":"def","term":"현대행정의 합법성","text":"입법국가에 비해 현대행정의 합법성은 상황에 따라 신축성을 부여하는 법의 적합성을 강조한다"},{"t":"tree","title":"외부효과","root":"외부효과란 시장을 거치지 않고 제3자에게 이익을 주거나 비용을 부담시키는 행위이다","branches":[["부정적 외부효과","불법주차, 환경오염 등은 부정적 외부효과를 야기 시키는 행위이며 해결하기 위해 조세를 부과할 수도 있다"],["긍정적 외부효과","대표적인 예는 교육, 교통정리 등이 있다"]]},{"t":"tree","title":"사회서비스 공급","root":"공공서비스 공급방식","branches":[["민간위탁","공공서비스의 생산을 민간에 위탁하는 방법 중의 하나이다"],["전자 이용권","보건복지부는 각종 돌봄서비스에서 전자 이용권을 제공하고 있다"],["맞춤형 서비스","소비자 중심의 맞춤형 사회서비스가 강조되면서 서비스가 확대되고 있다"],["확대 분야","노인, 장애인, 보육 정책 등에서 서비스가 확대되고 있다"]]},{"t":"table","title":"정부실패 원인","head":["원인","내용"],"rows":[["공유재적 성격","정부예산의 공유재적 성격 때문에 자원배분의 비효율성이 발생한다"],["정치적 보상기제","선거에 민감한 정치인들의 정치적 보상기제로 인해 사회문제가 과장되거나 단기적 해결책에 그치는 경우가 발생한다"],["목표의 대치","사회문제 해결의 목표보다는 내부적인 절차와 규칙에 집착하는 정부조직 목표의 대치 (displacement) 현상이 발생한다"]]}],"4":[{"t":"tree","title":"정책의제화 요인","root":"정책의제화될 가능성","branches":[["행위자와 대상 집단","사회 이슈와 관련된 행위자가 많고, 문제해결을 위한 다수의 정책 대상 집단에게 영향을 미치는 경우 보다 쉽게 정책의제화될 수 있다"],["피해","사회문제로 인한 피해자 숫자가 많거나 피해의 사회적 의미가 중대할수록 정책의제로 채택될 가능성이 높다"],["관심","국민적 관심과 집결도가 높거나 특정 사회 이슈에 대해 정치인의 관심도가 클수록 정책 의제화될 가능성이 높다"],["요구 집단","정책의제화를 요구하는 집단의 규모와 영향력이 클수록 정책의제화될 가능성이 높다"],["점화장치","위기나 재난 등 극적 사건은 사회문제를 정부의제화 시키는 점화장치에 해당된다"]]},{"t":"table","title":"의제 유형","head":["유형","내용"],"rows":[["공중의제","사회문제 혹은 사회적 쟁점이 한 단계 더 나아가 일반 공중의 주목을 받게 된 의제를 말한다"],["동원형","사회문제가 정부의제로 먼저 채택되고, 정부의 의도적인 노력에 의해서 공중의제로 확산되는 경우를 말한다"],["내부접근형","선진국의 경우, 특수 이익집단이 비밀리에 정부의 혜택을 보려는 외교ㆍ국방정책 등에서 주로 나타난다"]]}],"5":[{"t":"table","title":"정책결정모형","head":["모형","내용"],"rows":[["점증모형","정책대안의 선택과 가치판단은 분리하기 어려운 것으로 보며, 정책결정과정을 약간의 향상을 위해 그럭저럭 헤쳐 나가는 과정으로 본다"],["만족모형","인간의 능력에 한계가 있으므로 최적의 대안이 아닌 만족하는 정도의 대안을 결정한다"],["최적모형","비정형적인 정책결정 시 창의성이나 통찰력 같은 초합리성을 중요시 한다"],["쓰레기통모형","고도로 불확실한 조직상황하에서의 정책결정양태를 설명한다"],["무의사결정론","다원주의에 대한 비판적 시각에서 등장하였다"]]},{"t":"vs","title":"정책네트워크","cols":[{"name":"이슈네트워크","items":["정책공동체에 비해 상대적으로 많은 이해관계자와 느슨한 관계를 가정한다"]},{"name":"정책공동체","items":["다양한 내·외부 전문가 집단의 참여를 강조하는 점에서 하위정부모형과는 차별화된다"]},{"name":"철의 삼각","items":["폐쇄적 경계를 강조하고, 배타성이 매우 강하다"]}]},{"t":"table","title":"권력모형","head":["모형","내용"],"rows":[["마르크스주의","현대국가는 모든 자본가 계층의 공통된 이해관계를 대변하기 위한 위원회와 같다"],["엘리트주의","지배계층은 모든 정책과정을 장악하고 영향력을 행사하며 정책의 혜택을 누린다"],["제도주의","정책분석의 초점은 정부제도의 공식적ㆍ법적 기구에 맞추는 것이다"]]}],"6":[{"t":"tree","title":"정책집행","root":"정책집행","branches":[["정책목표 달성","정책결정의 결과물인 정책목표를 달성해 가는 과정을 정책집행으로 이해한다"],["상호작용","정책집행을 다수의 참가자들 사이의 상호작용으로 이해한다"],["일선관료","일선관료의 적절한 재량 부여를 강조한다"],["대상집단","집행의 영향을 받는 대상집단의 행태와 참여를 강조한다"],["목표 명확화","정책이 추구하는 목표를 분명히 하고, 정책결정자의 의도를 정확히 이해할수록 정책은 보다 효과적으로 집행될 수 있다"],["집행지상주의","바람직한 정책은 실현가능한 정책이라는 집행지상주의에 빠질 수 있다"]]},{"t":"def","term":"정책결정 연구의 초점","text":"정책이 결과물을 창출하는 과정에서 정책결정자가 어떤 역할을 했는지에 관심이 있다","ex":["정책결정단계에서 주된 역할을 하는 참여자와 정책내용에 초점을 맞춘다"]},{"t":"table","title":"정책평가의 타당성과 신뢰도","head":["개념","내용"],"rows":[["외적 타당성","정책평가 결과의 일반화 가능성을 의미한다"],["내적 타당성","정책이 집행된 이후에 나타나는 변화가 정책에 기인한 것인지, 다른 요인 때문인지를 밝히는 것과 관련된다"],["내적 타당성 저해 요인","선정요인, 성숙요인, 역사요인 등을 들 수 있다"],["신뢰도","동일한 측정도구를 반복해서 사용했을 때 동일한 결과를 얻을 확률을 의미한다"]]}],"7":[{"t":"tree","title":"신행정론","root":"인간행태의 발전과 쇄신적 가치관을 중시한다","branches":[["인간관","인간을 자아실현인ㆍ복잡인으로 파악한다"],["다원화","가치의 다원화 및 행정현상의 다양성을 인정한다"],["가치","효과성ㆍ생산성ㆍ민주성ㆍ대응성ㆍ사회적 적실성과 종합적인 행정개혁을 중시한다"],["개방체제","조직을 환경과 상호작용하는 동태적ㆍ유기체적 개방체제로 파악한다"]]},{"t":"tree","title":"인간관계론","root":"인간관계론","branches":[["비공식 집단","비공식적 집단의 역할을 강조한다"],["호손 실험","메이요(E. Mayo)의 호손(Hawthorne) 실험은 인간관계론의 형성에 영향을 주었다"],["생산성","과학적 관리론과 마찬가지로 생산성 향상을 추구한다"],["사회심리적 요인","작업환경이나 물리적 조건보다 조직구성원의 사회심리적 요인을 중시한다"]]}],"8":[{"t":"vs","title":"기계적 조직과 학습조직","cols":[{"name":"기계적 조직","items":["위계적ㆍ경직적 조직문화를 갖는다","경쟁을 중시한다","수직적 구조이다","정보가 최고관리층에 집중된다"]},{"name":"학습조직","items":["적응적 조직문화를 갖는다","협력을 중시한다","수평적 구조를 지향한다","정보가 조직원들에게 공유된다"]}]},{"t":"def","term":"네트워크 구조","text":"네트워크 구조의 협력적 연계는 조직 간에서 뿐만 아니라 조직 내에서도 형성될 수 있다"},{"t":"cause","title":"조직 환경 변화","causes":["조직이 속한 사회의 민주화가 촉진되고 있다","기술과 환경이 격동적으로 변화하고 있다"],"result":"조직 변화 요구","effects":["고객에게 신속하고 대응적인 서비스 요구가 증가하고 있다","조직구성원들의 참여 확대와 창의성 발현이 요구되고 있다"]},{"t":"def","term":"행정위원회","text":"방송통신위원회, 공정거래위원회와 같은 행정위원회는 결정권한을 갖고 있으며 집행까지 책임을 진다"}],"9":[{"t":"table","title":"공직봉사동기","head":["차원","내용"],"rows":[["전제","공공조직과 민간조직 종사자 간 동기의 차이를 전제로 한다"],["합리적 차원","공익 추구를 함으로써 자신의 이익도 극대화하려는 것이다"],["규범적 차원","국가에 충성하고 사회정의를 달성하고자 하는 것이다"],["감성적 차원","사회적으로 중요한 정책에 대한 몰입을 특징으로 한다"]]},{"t":"vs","title":"거래적 리더십과 변혁적 리더십","cols":[{"name":"거래적 리더십","items":["조직구성원의 보상을 통한 교환관계에서 형성된다","예외에 의한 관리를 추구한다"]},{"name":"변혁적 리더십","items":["카리스마적 리더십을 기반으로 한다","구성원들에게 장기적 비전을 제시하여 열정을 고무시킨다"]}]},{"t":"table","title":"동기이론","head":["이론","내용"],"rows":[["앨더퍼(C. Alderfer)의 ERG이론","인간의 욕구를 계층화한 점에서는 머슬로(A. Maslow)와 공통된 견해를 지니고 있다"],["위생요인","주로 생리적 욕구, 안전욕구 등을 만족시키는 요인들이다"]]}],"10":[{"t":"tree","title":"직위분류제","root":"조직에 있는 직위를 직무의 종류와 수준에 따라 분류해 관리하는 제도이다","branches":[["형평성","동일 노무에 대한 동일 보수를 지급하는 보수 체계의 형평성을 확보할 수 있다"],["직무분석","직무를 종류별로 구분해 직렬과 직군을 형성하는 작업이다"],["직무평가","직무를 수준별로 구분해 직급과 등급을 형성하는 작업이다"],["직위","1명의 공무원에게 부여할 수 있는 직무와 책임을 말한다"],["직렬","직무의 종류가 유사하고 그 책임과 곤란성의 정도가 서로 다른 직급의 군을 말한다"]]},{"t":"tree","title":"중앙인사기관","root":"중앙인사기관","branches":[["기능","각 행정기관의 합리적 인사운영, 인력의 효율적 활용, 공무원의 공직규범 기준 등 제공 기능을 담당한다"],["유형","행정수반으로부터의 독립성과 다수 위원들의 협의에 의한 의사결정을 하는 합의성 등을 기준으로 유형화할 수 있다"],["우리나라","인사관리기능을 수행하기 위해 각 부처의 인사기관과 각 지방자치단체의 인사기관이 있다"],["현재","현재 우리나라의 중앙인사기관은 국무총리 소속의 인사혁신처이다"]]},{"t":"def","term":"공무원 제도","text":"실적과 자격에 의해 임용되며 신분이 보장된다","ex":["조직 내의 직위들을 각 직위에 배당된 직무의 속성에 따라 분류ㆍ관리하는 제도를 말한다"]}],"12":[{"t":"tree","title":"이해충돌","root":"공무원의 직무상 의무와 개인적 이해의 충돌을 의미한다","branches":[["회피 원칙","이해충돌 회피의 기본원칙은 “누구도 자신의 사건에 대해 판결할 수 없다”는 것이다"],["규제 이유","이해충돌 규제를 강조하는 이유는 주인-대리인 관계의 신뢰성 유지가 필요하기 때문이다"],["인사청문회","고위직 공무원의 인사청문회는 이해충돌의 가능성을 사전에 점검하는 의미가 있다"]]},{"t":"def","term":"정직","text":"1개월 이상 3개월 이하의 기간으로 하고, 정직 처분을 받은 자는 그 기간 중 공무원의 신분은 보유하나 직무에 종사하지 못하며 보수는 전액을 감한다"},{"t":"tree","title":"공직자의 금지 행위","root":"공직자","branches":[["미공개정보","직무수행 중 알게 된 비밀 또는 소속 공공기관의 미공개정보를 사적 이익을 위하여 이용하거나 제3자로 하여금 이용하게 하여서는 아니 된다"],["대가 수수","직무관련자에게 사적으로 노무 또는 조언ㆍ자문 등을 제공하고 대가를 받는 행위를 하여서는 아니 된다"],["공공기관 물품","공공기관이 소유하거나 임차한 물품ㆍ차량ㆍ선박ㆍ항공기ㆍ건물ㆍ토지ㆍ시설 등을 사적인 용도로 사용ㆍ수익하거나 제3자로 하여금 사용ㆍ수익하게 하여서는 아니 된다"],["퇴직자 접촉","직무관련자인 소속 기관의 퇴직자(공직자가 아니게 된 날부터 2년 이내인 자)와 사적 접촉(골프, 여행, 사행성 오락을 같이 하는 행위)을 하는 경우 소속기관장에게 신고하여야 한다"]]},{"t":"tree","title":"내부고발","root":"내부고발","branches":[["대상","일반적으로 조직 내에서 행해진 비윤리적 행위이다"],["발생 시기","내부고발의 대상이 되는 문제를 조직 내에서 해결할 장치가 없거나 제대로 작동되지 않을 때 주로 일어난다"],["성격","조직 내부의 비리를 대외적으로 폭로하는 외부적 행위이다"]]}],"13":[{"t":"table","title":"정부의 작성·제출 서류","head":["서류","내용"],"rows":[["성인지예산서","예산이 여성과 남성에게 미칠 영향을 미리 분석한 보고서"],["국가결산보고서","감사원의 검사를 거쳐 다음 연도 5월 31일까지 국회에 제출해야 한다"],["온실가스감축인지 결산서","예산이 온실가스를 감축하는 방향으로 집행되었는지를 평가하는 보고서"],["조세지출예산서","작성하고, 국회에 제출하는 예산안의 첨부서류에 이를 포함해야 한다"]]}],"14":[{"t":"tree","title":"점증주의 예산결정","root":"예산결정이론","branches":[["제한된 합리성","인간의 능력부족과 환경의 불확실성에 기초한 제한된 합리성을 전제로 한다"],["소폭의 변화","예산 결정은 전년도 예산 규모에 근거해 소폭의 변화만이 이뤄질 뿐이라고 주장한다"],["상호 조절","이해당사자들의 협상과 적응 등 상호 조절과정을 강조한다"],["한계","사회적 불안정성이 높은 경우 예산 결정을 설명하기 힘들다"]]},{"t":"table","title":"예산 용어","head":["용어","내용"],"rows":[["기금운용계획안","국회는 정부가 제출한 기금운용계획안의 주요항목 지출금액을 증액하고자 하는 때에는 미리 정부의 동의를 얻어야 한다"],["이체(移替)","폐지되거나 기능이 이관된 기관의 예산을 신설된 기관의 예산으로 재분배하는 것"]]},{"t":"tree","title":"결산","root":"결산","branches":[["정의","회계연도에서 국가의 수입과 지출 실적을 확정적 계수로 표시하는 행위이다"],["기능","예산의 범위 내에서 재정활동을 했는지 확인하고 그 결과를 재정운용에 반영하는 과정이다"],["감사 요구","결산 심의를 한 결과 문제가 있는 특정사안에 대하여 감사원에 감사를 요구할 수 있다"],["시정 요구","재정운용의 비능률이 발견된 경우 시정을 요구할 수 있고 차년도 예산과정에서 쟁점화될 수 있다"]]}],"15":[{"t":"tree","title":"구조적 접근방법","root":"행정체계의 구조적 설계를 개선함으로써 행정개혁의 목표를 달성하려는 접근방법이다","branches":[["추진 내용","분권화 수준의 개선, 권한배분의 개편, 명령계통의 수정, 작업집단의 설계 등을 추진한다"],["주된 목표","기능중복의 제거 및 표준적 절차의 간소화 등이다"],["분권화","조직의 분권화를 통해 조직계층의 단순화, 명령과 책임 등을 명확히 할 수 있다"]]},{"t":"table","title":"정부별 행정개혁","head":["정부","내용"],"rows":[["제3공화국","행정개혁조사위원회에 의해 추진되었다"],["제4공화국","서정쇄신운동의 일환으로 전개되었다"],["김영삼정부","행정절차법과 공공기관의 정보공개에 관한 법률을 제정해 행정의 투명성을 제고하고자 하였다"],["김대중정부","행정개혁을 위해 정부혁신추진위원회를 설치하였다"]]}],"16":[{"t":"tree","title":"전자정부","root":"전자정부","branches":[["연계·통합","부처 간 장벽이 없는 네트워크를 통해 서비스 연계ㆍ통합이 가능한 정부이다"],["모바일","모바일 기기 등으로 어디서나 편리한 서비스를 제공하는 정부이다"],["실시간","국민의 수요에 실시간으로 반응하는 서비스를 제공하는 정부이다"],["참여·소통","참여ㆍ소통으로 수요자가 원하는 서비스와 정보를 제공하는 정부이다"]]},{"t":"def","term":"지식행정","text":"지식사회를 설계하고 지식관리를 통해 가치를 창출하고 극대화하는 것을 의미한다"},{"t":"vs","title":"전자정부의 역기능과 순기능","cols":[{"name":"역기능","items":["전자정부 발전으로 인한 정보화의 역기능은 사회적 질서와 안전을 위협하는 디지털 위험으로 진행될 수 있다"]},{"name":"필요한 방향","items":["일반적으로 정보는 공공재 성격이 강하기 때문에 행정정보의 비대칭성 문제는 해소 내지 완화되어야 하는 것이 바람직하다","정부의 맞춤형 전자서비스와 빅데이터 산업 고도화 차원에서 개인정보의 행정기관 간 공동 활용은 중요하다","전자정부 서비스는 이용자들의 거래비용과 기회비용 및 민원업무 감소에 기여한다"]}]}],"17":[{"t":"tree","title":"지방자치","root":"지방자치","branches":[["본질","지역주민이 그 지역의 제반 문제를 스스로 결정하고 처리하는 것이다"],["주민","일정기간 지역에 거주하지 않았더라도 주민등록만 되어 있다면 지방자치법상 주민으로서의 권리와 의무의 주체가 된다"],["대표성","대의민주제를 포함한 지방자치단체의 주민대표성과 민주성을 강조한다"],["풀뿌리 민주주의","지방자치는 지방분권을 전제로 하며, 주민참여는 ‘풀뿌리 민주주의’ 원리를 구현한다"],["정책 실험장","지방자치단체라는 공법인을 통해 주민에게 필요한 주요 정책의 실험장 역할을 한다"],["능률성과 책임성","지역특성에 맞는 행정과 정책을 통해 행정의 능률성과 책임성을 확립한다"]]},{"t":"def","term":"고유권설","text":"자치권을 인간의 자연권과 마찬가지로 본래적이고 침해할 수 없는 고유한 권리라고 본다"}],"18":[{"t":"tree","title":"특별지방자치단체","root":"특별지방자치단체","branches":[["설치","두 개 이상의 지방자치단체가 특정한 목적을 위하여 법인으로서의 특별지방자치단체를 설치할 수 있다"],["법인","특별지방자치단체는 법인으로 한다"],["장","구성 지방자치단체의 장은 특별지방자치단체의 장을 겸할 수 있다"],["의회","특별지방자치단체의 의회는 규약으로 정하는 바에 따라 구성 지방자치단체의 의회 의원으로 구성한다"],["구역","특별지방자치단체의 구역은 특별한 사정이 있을 때에는 해당 지방자치단체 구역의 일부만을 구역으로 할 수 있다"]]},{"t":"tree","title":"지방자치단체의 종류","root":"지방자치단체","branches":[["종류","지방자치단체에는 특별시, 광역시, 도, 특별자치도, 특별자치시와 시ㆍ군ㆍ구(자치구)가 포함된다"],["구","특별시ㆍ광역시 또는 특별자치시가 아닌 인구 50만 이상의 시는 자치구가 아닌 구를 둘 수 있다"],["법령의 범위","모든 지방자치단체는 법령의 범위를 벗어나 사무 처리와 조례 제정을 할 수 없다"]]}],"19":[{"t":"tree","title":"사무배분","root":"국가와 지방자치단체 간 사무배분","branches":[["중복 금지","국가는 국가와 지방자치단체 간의 사무를 주민의 편익증진 등을 고려하여 서로 중복되지 아니하도록 배분하여야 한다"],["포괄적 배분","국가가 지방자치단체에 사무를 배분할 때에는 관련 사무를 포괄적으로 배분하여야 한다"],["조직과 규모","지방자치단체는 조직과 운영을 합리적으로 하고 규모를 적절하게 유지하여야 한다"],["조례","시ㆍ군 및 자치구는 해당 구역을 관할하는 시ㆍ도의 조례를 위반하여 사무를 처리할 수 없다"],["감사","행정안전부장관은 지방자치단체의 자치사무에 관하여 법령 위반사항에 대해서만 서류·장부 또는 회계를 감사할 수 있다"]]},{"t":"vs","title":"자치경찰과 국가경찰","cols":[{"name":"자치경찰","items":["2006년 제주특별자치도 자치경찰제 시범 도입에 이어 2021년부터 본격적으로 자치경찰제가 시행되었다","자치경찰사무로 지역 내 주민의 생활안전 활동과 교통활동에 관한 사무가 있다","광역자치단체장 소속으로 시ㆍ도자치경찰위원회가 자치경찰사무를 관장한다"]},{"name":"국가경찰","items":["국가경찰사무는 국민의 생명ㆍ신체 및 재산의 보호, 범죄의 예방ㆍ진압 및 수사 등이다"]}]},{"t":"def","term":"주민소송","text":"주민이 감사청구한 일정한 재무회계 사항과 관련이 있는 지방자치단체의 장 등의 위법한 행위 등에 대하여 손해를 배상하게 하는 제도이다"},{"t":"table","title":"주민의 권리","head":["주민","내용"],"rows":[["주민 A씨(30세)","자신이 살고 있는 지역의 지방자치단체 발전과 운영에 기여할 수 있다"],["○○시 주민 B씨(20세)","청년일자리 창출에 관한 조례의 필요성에 따라 요건을 갖추어 ○○시 조례의 제정을 청구하였다"]]}]};
