(window.TNQ=window.TNQ||[]).push({"terms":{"합리적 선택이론":{"d":"개인이 자기 이익을 계산해 가장 유리한 선택을 한다고 가정하고 행동을 설명하는 이론.","r":["공유재의 비극"]},"공유재의 비극":{"d":"모두가 쓸 수 있는 자원을 각자 이익만 따라 쓰다가 결국 고갈되는 현상.","r":["합리적 선택이론"]},"행태주의":{"d":"관찰 가능한 행동과 사실만 경험적으로 연구해 사회과학을 과학으로 만들려는 입장.","r":["정통 행정학","정치행정일원론"]},"정치행정일원론":{"d":"행정이 정책의 결정에도 관여하므로 정치와 행정을 나눌 수 없다고 보는 관점.","r":["정통 행정학","행태주의"]},"정통 행정학":{"d":"능률 높은 관리를 중심으로 행정을 정치와 구별하려 한 초기 행정학.","r":["정치행정일원론"]},"내부시장화":{"d":"정부 조직 안에 경쟁이나 계약 관계를 들여 효율을 높이려는 서비스 공급 방식.","r":[]},"부정적 외부효과":{"d":"거래 당사자 밖의 제3자에게 대가 없이 손해를 입히는 활동의 영향.","r":[]},"전자 이용권":{"d":"정부가 이용자에게 주는 전자 방식의 지불 수단으로 서비스 제공기관에서 쓴다.","r":[]},"목표의 대치":{"d":"수단이던 절차와 규칙이 목표가 되어 조직의 원래 목표가 밀려나는 현상.","r":[]},"정책의제화":{"d":"사회문제가 정부가 해결해야 할 정책 문제로 채택되는 과정.","r":["점화장치","정부의제","공중의제"]},"점화장치":{"d":"위기나 재난처럼 문제를 갑자기 의제 위로 끌어올리는 극적인 사건.","r":["정책의제화"]},"공중의제":{"d":"일반 국민 다수가 주목하고 정부가 다뤄야 한다고 여기는 문제.","r":["정부의제","정책의제화"]},"정부의제":{"d":"정부가 공식적으로 해결 대상으로 삼아 검토하기로 한 문제.","r":["공중의제","정책의제화"]},"정책공동체":{"d":"소수의 전문가와 이해관계자가 정책을 두고 깊이 교류하는 비교적 안정된 연결망.","r":["하위정부모형"]},"하위정부모형":{"d":"관료, 의회 위원회, 이익집단이 폐쇄적으로 결탁해 특정 정책을 주도하는 모형.","r":["정책공동체"]},"일선관료":{"d":"시민을 직접 만나 정책을 집행하며 현장에서 재량을 쓰는 공무원.","r":[]},"집행지상주의":{"d":"정책이 바람직한지보다 집행이 가능한지를 앞세우는 태도.","r":[]},"선정요인":{"d":"처음부터 집단 사이에 차이가 있어 결과가 왜곡되는 내적 타당성 저해 요인.","r":["성숙요인","역사요인"]},"성숙요인":{"d":"시간이 지나며 대상 자체가 변해 생긴 변화를 정책 효과로 오인하게 하는 요인.","r":["선정요인","역사요인"]},"역사요인":{"d":"평가 기간 중 일어난 다른 사건이 결과에 영향을 주는 내적 타당성 저해 요인.","r":["선정요인","성숙요인"]},"개방체제":{"d":"환경과 자원과 정보를 주고받으며 존속하는 체제.","r":[]},"인간관계론":{"d":"조직의 생산성이 비공식 집단과 구성원의 심리에 달려 있다고 보는 이론.","r":["과학적 관리론"]},"과학적 관리론":{"d":"작업을 표준화하고 시간과 동작을 연구해 능률을 높이려는 이론.","r":["인간관계론"]},"카리스마적 리더십":{"d":"지도자의 비범한 매력과 신뢰로 구성원을 이끄는 리더십.","r":["예외에 의한 관리"]},"예외에 의한 관리":{"d":"기준에서 벗어난 예외 상황에만 관리자가 개입하는 방식.","r":["카리스마적 리더십"]},"직렬":{"d":"직무의 종류가 비슷하지만 책임과 곤란성의 정도가 다른 직급의 군.","r":["직군","직급"]},"직군":{"d":"직무 성질이 유사한 직렬을 한데 묶은 단위.","r":["직렬","직급"]},"직급":{"d":"직무의 종류와 곤란성과 책임도가 비슷해 같은 자격과 보수를 적용하는 직위의 군.","r":["직렬","직군"]},"이해충돌":{"d":"공직자의 사적 이해관계가 직무의 공정한 수행과 부딪히는 상황.","r":["미공개정보","주인-대리인"]},"인사청문회":{"d":"고위 공직 후보자의 자질과 도덕성을 국회가 임명 전에 검증하는 절차.","r":["이해충돌"]},"미공개정보":{"d":"직무 중 알게 되어 일반에 공개되지 않은 정보.","r":["이해충돌"]},"주인-대리인":{"d":"주인이 일을 맡긴 대리인이 주인과 다른 이익을 따를 수 있는 위임 관계.","r":["이해충돌"]},"내부고발":{"d":"조직 구성원이 그 조직의 불법이나 부정을 외부에 알리는 행위.","r":[]},"제한된 합리성":{"d":"인지 능력과 정보의 한계로 사람이 완전한 합리성에 이르지 못한다는 개념.","r":[]},"기금운용계획안":{"d":"정부가 특정 목적으로 운용하는 기금의 수입과 지출 계획.","r":[]},"분권화":{"d":"의사결정 권한을 하위 단위로 넘기는 것.","r":[]},"특별지방자치단체":{"d":"둘 이상의 지방자치단체가 특정 사무를 공동 처리하려고 설치하는 법인.","r":["자치구","조례"]},"자치구":{"d":"특별시와 광역시 안에 두는 기초자치단체인 구.","r":["특별지방자치단체"]},"조례":{"d":"지방자치단체가 법령의 범위 안에서 지방의회 의결로 정하는 자치법규.","r":["특별지방자치단체"]},"풀뿌리 민주주의":{"d":"주민이 지방 수준에서 직접 참여해 이루는 민주주의.","r":[]},"서정쇄신운동":{"d":"행정과 공직 사회를 새롭게 고치려고 전개된 개혁 운동.","r":[]},"행정절차법":{"d":"행정청이 처분을 할 때 따라야 할 절차를 정한 법.","r":[]},"다원주의":{"d":"여러 이익집단이 경쟁하며 권력이 분산되어 정책에 영향을 준다고 보는 입장.","r":["초합리성"]},"초합리성":{"d":"논리적 분석을 넘어 직관과 창의성까지 활용하는 성격.","r":["다원주의"]},"자치경찰제":{"d":"지방자치단체가 생활안전 같은 지역 치안 사무를 맡아 운영하는 경찰 제도.","r":[]}},"notes":{"1887년 윌슨(W. Wilson)은 “행정의 연구(The Study of Administration)”에서 행정의 본질을 관리로 파악하였다":"윌슨은 정치와 행정을 나누어 행정을 정치와 무관한 관리의 영역으로 보았습니다.","1920년대에서 1930년대에 걸쳐 능률에 기초한 관리를 주장하는 정통 행정학의 모습을 갖추게 되었다":"능률을 높이는 관리 기법을 중심에 둔 정통 행정학이 이 시기에 틀을 잡았습니다.","1930년대 이후 등장한 정치행정일원론은 행정의 정책형성 기능을 중시하였다":"행정이 집행만 하지 않고 정책을 만드는 데도 관여한다고 보는 관점이 나타났습니다.","1940년대 이후 행정학의 과학화를 위하여 사실판단적인 것만을 연구대상으로 삼았다":"자연과학처럼 검증 가능한 경험적 사실만 연구해 행정학을 과학으로 만들려 했습니다.","1940년대 이후 행태주의는 행정학의 과학화를 위하여 사실판단적인 것만을 연구대상으로 삼았다":"행태주의가 가치판단을 제쳐 두고 사실만 연구한 것은 학문의 과학성을 높이려는 의도였습니다.","1990년대의 영국 행정개혁 일환으로 시행되었다":"영국이 공공업무를 직접 할지 맡길지 정하려고 도입한 개혁 수단이었습니다.","1개월 이상 3개월 이하의 기간으로 하고, 정직 처분을 받은 자는 그 기간 중 공무원의 신분은 보유하나 직무에 종사하지 못하며 보수는 전액을 감한다":"1개월 이상 3개월 이하 동안 공무원 신분은 두되 일을 못 하고 보수 전액이 줄어드는 징계입니다.","1명의 공무원에게 부여할 수 있는 직무와 책임을 말한다":"한 사람의 공무원이 맡는 일과 책임의 단위로 직위분류제의 가장 기본 단위예요.","2006년 제주특별자치도 자치경찰제 시범 도입에 이어 2021년부터 본격적으로 자치경찰제가 시행되었다":"2006년 제주의 시범 운영을 거쳐 2021년에 제도가 본격 가동되었음을 말해 줍니다.","가치와 사실문제를 엄격하게 구분하고 자유와 평등의 가치를 연구 대상에서 제외한다":"가치판단은 검증할 수 없다고 보아 연구에서 빼고 관찰되는 사실만 분석하려는 태도예요.","가치의 다원화 및 행정현상의 다양성을 인정한다":"가치가 사람마다 다르고 행정 현상도 한 가지로 설명되지 않는다고 인정합니다.","각 행정기관의 합리적 인사운영, 인력의 효율적 활용, 공무원의 공직규범 기준 등 제공 기능을 담당한다":"부처가 인사를 합리적으로 하도록 기준과 규범을 제공하고 인력 활용을 조정합니다.","감사원의 검사를 거쳐 다음 연도 5월 31일까지 국회에 제출해야 한다":"감사원이 검사한 뒤 다음 연도 5월 31일까지 국회에 내야 하는 결산 서류입니다.","결산 심의를 한 결과 문제가 있는 특정사안에 대하여 감사원에 감사를 요구할 수 있다":"심의 결과 의심스러운 사안이 있으면 국회가 감사원에 직접 조사를 요청할 수 있습니다.","고객에게 신속하고 대응적인 서비스 요구가 증가하고 있다":"시민이 빠르고 맞춤형인 서비스를 기대하게 되어 조직이 민감하게 반응해야 합니다.","고도로 불확실한 조직상황하에서의 정책결정양태를 설명한다":"목표와 참여자가 불분명한 조직에서는 문제와 해결책이 우연히 만나 결정이 이루어진다고 봅니다.","고위직 공무원의 인사청문회는 이해충돌의 가능성을 사전에 점검하는 의미가 있다":"임명되기 전에 직무와 재산 등 이해충돌 소지를 미리 검증해 문제를 막는 장치예요.","공공기관이 소유하거나 임차한 물품ㆍ차량ㆍ선박ㆍ항공기ㆍ건물ㆍ토지ㆍ시설 등을 사적인 용도로 사용ㆍ수익하거나 제3자로 하여금 사용ㆍ수익하게 하여서는 아니 된다":"공공 자산은 국민 전체의 것이라 개인이나 제3자가 사적으로 써서 이익을 얻는 것을 막습니다.","공공서비스의 생산을 민간에 위탁하는 방법 중의 하나이다":"정부가 책임은 지되 서비스를 만드는 일은 민간 기관에 맡기는 공급 방식입니다.","공공조직과 민간조직 종사자 간 동기의 차이를 전제로 한다":"공무원은 민간 종사자와 다른 동기로 일한다는 가정에서 출발하는 개념입니다.","공식적 제도나 구조는 물론 비공식적 제도와 규범도 중요하게 강조한다":"제도를 법과 조직 같은 공식 요소뿐 아니라 관행과 규범까지 포함해 넓게 봅니다.","공익 추구를 함으로써 자신의 이익도 극대화하려는 것이다":"공익을 늘리는 일이 곧 자기 이익도 키운다고 계산해 공공 활동에 참여하는 동기예요.","과학적 관리론과 마찬가지로 생산성 향상을 추구한다":"인간관계론도 과학적 관리론처럼 생산성을 높이려 하지만 방법은 사람의 마음을 살피는 쪽이에요.","관료는 사회문제를 해결하는 과정에서 협상과 중재 기능을 담당한다":"관료가 명령하는 대신 여러 이해관계자의 입장을 조율하는 조정자 역할을 맡습니다.","관료들이 정책결정을 해야만 한다는 적극적 정치행정일원론을 주장한다":"정치와 행정이 따로가 아니라 관료도 정책을 정하는 데 적극 관여해야 한다는 입장입니다.","광역자치단체장 소속으로 시ㆍ도자치경찰위원회가 자치경찰사무를 관장한다":"광역단체장 아래 설치된 위원회가 자치경찰사무를 총괄해 관리합니다.","구성원들에게 장기적 비전을 제시하여 열정을 고무시킨다":"먼 미래의 목표를 보여 주어 구성원이 눈앞의 이익을 넘어 일에 열정을 갖게 합니다.","구성 지방자치단체의 장은 특별지방자치단체의 장을 겸할 수 있다":"별도로 장을 뽑지 않고 구성 지방자치단체의 장이 겸직하도록 허용합니다.","국가가 지방자치단체에 사무를 배분할 때에는 관련 사무를 포괄적으로 배분하여야 한다":"관련 사무를 한꺼번에 넘겨야 지자체가 일을 끝까지 책임지고 처리할 수 있어요.","국가경찰사무는 국민의 생명ㆍ신체 및 재산의 보호, 범죄의 예방ㆍ진압 및 수사 등이다":"생명과 신체와 재산을 보호하고 범죄를 예방하고 수사하는 전국적 통일성이 필요한 사무예요.","국가는 국가와 지방자치단체 간의 사무를 주민의 편익증진 등을 고려하여 서로 중복되지 아니하도록 배분하여야 한다":"같은 일을 국가와 지자체가 겹쳐 하면 낭비라 주민 편익을 고려해 사무를 나눠야 합니다.","국가에 충성하고 사회정의를 달성하고자 하는 것이다":"국가에 대한 충성심과 사회정의 실현이라는 규범과 가치에 이끌려 일하는 동기입니다.","국민의 수요에 실시간으로 반응하는 서비스를 제공하는 정부이다":"수요가 생기는 즉시 대응하는 정부라서 처리 지연이 줄어드는 형태예요.","국민적 관심과 집결도가 높거나 특정 사회 이슈에 대해 정치인의 관심도가 클수록 정책 의제화될 가능성이 높다":"국민과 정치인의 관심이 클수록 정부가 문제를 외면하기 어려워 정책의제로 채택됩니다.","국회는 정부가 제출한 기금운용계획안의 주요항목 지출금액을 증액하고자 하는 때에는 미리 정부의 동의를 얻어야 한다":"국회는 주요항목 지출을 늘리기 전에 정부 동의를 받아야 해 증액 권한에 제한이 있습니다.","급속한 시장변화 속에 있는 업무를 포함한다":"시장 상황이 빨리 바뀌는 업무는 민간이 더 잘 대응할 수 있어 적합한 대상에 들어갑니다.","기능중복의 제거 및 표준적 절차의 간소화 등이다":"같은 일을 하는 기능이 겹치는 것을 없애고 업무 절차를 표준화해 단순하게 만들려 합니다.","기술과 환경이 격동적으로 변화하고 있다":"변화 속도가 빨라져 정해진 절차만으로는 대처하기 어려워 유연한 조직이 요구됩니다.","내부고발의 대상이 되는 문제를 조직 내에서 해결할 장치가 없거나 제대로 작동되지 않을 때 주로 일어난다":"조직 안에서 문제를 바로잡을 통로가 없거나 작동하지 않을 때 밖으로 알리게 됩니다.","내부시장화 또는 민간화 등 다양한 서비스 제공방식을 제시한다":"검증 결과에 따라 정부 안에 경쟁을 들이거나 민간에 넘기는 등 여러 대안 중에서 고릅니다.","네트워크 구조의 협력적 연계는 조직 간에서 뿐만 아니라 조직 내에서도 형성될 수 있다":"협력 관계는 조직 사이뿐 아니라 한 조직의 부서 사이에도 연결망 형태로 만들 수 있어요.","노인, 장애인, 보육 정책 등에서 서비스가 확대되고 있다":"돌봄 수요가 큰 노인, 장애인, 보육 분야에서 서비스 제공 범위가 늘어나고 있어요.","다양한 내·외부 전문가 집단의 참여를 강조하는 점에서 하위정부모형과는 차별화된다":"하위정부모형은 소수의 폐쇄 집단이지만 이 모형은 더 다양한 전문가가 참여하는 점이 다릅니다.","다원주의에 대한 비판적 시각에서 등장하였다":"힘 있는 집단이 자기에게 불리한 문제는 논의조차 되지 못하게 막을 수 있다는 지적이에요.","대의민주제를 포함한 지방자치단체의 주민대표성과 민주성을 강조한다":"주민이 뽑은 대표가 지방자치단체를 이끌므로 주민 의사를 대표하고 민주적인 운영을 요구합니다.","대표적인 예는 교육, 교통정리 등이 있다":"교육이나 교통정리는 당사자 말고도 사회 전체가 이익을 보는 긍정적 외부효과의 사례예요.","동일 노무에 대한 동일 보수를 지급하는 보수 체계의 형평성을 확보할 수 있다":"같은 일을 하면 같은 보수를 받으므로 보수 체계가 공평하다는 평가를 얻기 쉽습니다.","동일한 측정도구를 반복해서 사용했을 때 동일한 결과를 얻을 확률을 의미한다":"같은 도구로 여러 번 재도 같은 값이 나오는 정도로 측정의 일관성을 가리킵니다.","두 개 이상의 지방자치단체가 특정한 목적을 위하여 법인으로서의 특별지방자치단체를 설치할 수 있다":"둘 이상의 자치단체가 특정 목적 사업을 함께 하려고 따로 법인을 만들 수 있습니다.","메이요(E. Mayo)의 호손(Hawthorne) 실험은 인간관계론의 형성에 영향을 주었다":"메이요가 호손 공장에서 한 연구로 작업 성과가 인간관계에 좌우됨을 보여 주었습니다.","모든 지방자치단체는 법령의 범위를 벗어나 사무 처리와 조례 제정을 할 수 없다":"지방자치단체의 사무와 조례는 법령이 허용하는 범위 안에서만 가능하다는 한계를 말합니다.","모바일 기기 등으로 어디서나 편리한 서비스를 제공하는 정부이다":"스마트폰 같은 기기로 시간과 장소에 구애받지 않고 행정서비스를 받는 형태입니다.","바람직한 정책은 실현가능한 정책이라는 집행지상주의에 빠질 수 있다":"실행 가능성만 따지다 보면 정책이 바람직한지 가리는 가치 논의가 뒷전으로 밀릴 수 있어요.","방송통신위원회, 공정거래위원회와 같은 행정위원회는 결정권한을 갖고 있으며 집행까지 책임을 진다":"합의제로 의사결정하는 기관이며 결정에 그치지 않고 집행의 책임까지 집니다.","보건복지부는 각종 돌봄서비스에서 전자 이용권을 제공하고 있다":"돌봄서비스 이용자가 정부가 준 전자 이용권으로 제공기관에서 서비스를 받는 방식입니다.","부처 간 장벽이 없는 네트워크를 통해 서비스 연계ㆍ통합이 가능한 정부이다":"부처 사이 칸막이 없이 시스템을 이어 서비스를 하나로 묶어 제공하는 정부를 말해요.","분권화 수준의 개선, 권한배분의 개편, 명령계통의 수정, 작업집단의 설계 등을 추진한다":"권한 배분과 명령계통 같은 조직의 틀 자체를 바꾸어 성과를 높이려는 방법입니다.","불법주차, 환경오염 등은 부정적 외부효과를 야기 시키는 행위이며 해결하기 위해 조세를 부과할 수도 있다":"시장 거래 밖에 있는 사람에게 손해를 주는 행위라서 조세를 매겨 그 비용을 행위자가 지게 합니다.","비공식적 집단의 역할을 강조한다":"공식 조직도에 없는 친분 중심의 모임이 구성원의 태도와 생산성에 영향을 준다고 봅니다.","비정형적인 정책결정 시 창의성이나 통찰력 같은 초합리성을 중요시 한다":"정해진 틀이 없는 결정에서는 직관과 영감처럼 합리성을 넘어서는 요소를 활용합니다.","사회문제가 정부의제로 먼저 채택되고, 정부의 의도적인 노력에 의해서 공중의제로 확산되는 경우를 말한다":"정부가 먼저 문제를 의제로 정한 뒤 홍보와 설득으로 국민의 지지를 이끌어 내는 경로입니다.","사회문제로 인한 피해자 숫자가 많거나 피해의 사회적 의미가 중대할수록 정책의제로 채택될 가능성이 높다":"피해자가 많거나 피해의 의미가 클수록 해결 요구가 커져 정책의제가 될 가능성이 높아집니다.","사회문제 해결의 목표보다는 내부적인 절차와 규칙에 집착하는 정부조직 목표의 대치 (displacement) 현상이 발생한다":"수단인 절차와 규칙이 목적이 되어 본래 목표인 문제 해결이 뒷전으로 밀리는 현상입니다.","사회문제 혹은 사회적 쟁점이 한 단계 더 나아가 일반 공중의 주목을 받게 된 의제를 말한다":"사회문제가 일부 집단의 쟁점에서 일반 국민 다수가 주목하는 의제로 올라선 단계입니다.","사회 이슈와 관련된 행위자가 많고, 문제해결을 위한 다수의 정책 대상 집단에게 영향을 미치는 경우 보다 쉽게 정책의제화될 수 있다":"관련 행위자와 영향받는 집단이 많을수록 관심이 커져 정부가 다룰 문제로 올라오기 쉽습니다.","사회적 불안정성이 높은 경우 예산 결정을 설명하기 힘들다":"사회가 불안정해 큰 변화가 필요할 때는 소폭 조정이라는 가정이 맞지 않아 설명이 어렵습니다.","사회적으로 중요한 정책에 대한 몰입을 특징으로 한다":"중요한 정책에 정서적으로 깊이 빠져드는 감정이 공직 봉사를 이끄는 동기예요.","서정쇄신운동의 일환으로 전개되었다":"행정을 새롭게 고치자는 서정쇄신운동의 한 갈래로 개혁이 진행되었습니다.","선거에 민감한 정치인들의 정치적 보상기제로 인해 사회문제가 과장되거나 단기적 해결책에 그치는 경우가 발생한다":"정치인은 표를 얻으려 눈에 띄는 문제를 부풀리고 눈앞의 성과를 내는 단기 해법을 택합니다.","선정요인, 성숙요인, 역사요인 등을 들 수 있다":"정책 외에 집단을 고른 방식, 시간에 따른 성숙, 외부 사건이 결과를 흐릴 수 있어요.","선진국의 경우, 특수 이익집단이 비밀리에 정부의 혜택을 보려는 외교ㆍ국방정책 등에서 주로 나타난다":"일반 국민에게는 알리지 않고 이익집단이 정부 내부와 직접 접촉해 의제를 정하는 유형이에요.","소비자 중심의 맞춤형 사회서비스가 강조되면서 서비스가 확대되고 있다":"획일적 서비스가 아니라 이용자의 필요에 맞춘 사회서비스로 공급 방식이 옮겨 가고 있습니다.","시ㆍ군 및 자치구는 해당 구역을 관할하는 시ㆍ도의 조례를 위반하여 사무를 처리할 수 없다":"하위인 시ㆍ군과 자치구는 상위 광역 단체가 정한 조례에 어긋나게 일할 수 없어요.","실적과 자격에 의해 임용되며 신분이 보장된다":"연줄이 아니라 능력으로 뽑고 정치적 이유로 함부로 쫓아내지 못하게 하는 제도입니다.","예산 결정은 전년도 예산 규모에 근거해 소폭의 변화만이 이뤄질 뿐이라고 주장한다":"새로 짜기보다 전년도 예산을 기준으로 조금씩 늘리거나 줄이는 방식이라고 설명합니다.","예산의 범위 내에서 재정활동을 했는지 확인하고 그 결과를 재정운용에 반영하는 과정이다":"예산대로 재정활동을 했는지 점검하고 그 결과를 다음 재정운용에 반영하는 과정이에요.","예산이 여성과 남성에게 미칠 영향을 미리 분석한 보고서":"예산이 남녀에게 각각 어떤 영향을 줄지 미리 분석해 성별 격차를 줄이려는 문서예요.","예산이 온실가스를 감축하는 방향으로 집행되었는지를 평가하는 보고서":"예산 집행이 온실가스 감축에 도움이 됐는지 사후에 평가한 결과를 담은 보고서예요.","예외에 의한 관리를 추구한다":"평소엔 간섭하지 않다가 기준에서 벗어난 일이 생겼을 때만 개입하는 관리 방식이에요.","오스트롬(E. Ostrom)은 ‘공유재의 비극’의 해결 방안으로 공동체 중심의 자치제도를 제시한다":"공유재를 모두가 남용해 고갈되는 문제를 이용 당사자들이 스스로 만든 규칙으로 풀 수 있다고 봅니다.","위계적ㆍ경직적 조직문화를 갖는다":"상하 위계가 뚜렷하고 규칙이 엄격해 변화에 느리게 반응하는 조직 문화입니다.","위기나 재난 등 극적 사건은 사회문제를 정부의제화 시키는 점화장치에 해당된다":"위기나 재난 같은 사건이 사람들의 관심에 불을 붙여 문제를 정부의제로 올리는 계기가 되어요.","이해당사자들의 협상과 적응 등 상호 조절과정을 강조한다":"이해당사자들이 협상하고 서로 맞춰 가며 합의를 이루는 과정에서 예산이 정해집니다.","이해충돌 규제를 강조하는 이유는 주인-대리인 관계의 신뢰성 유지가 필요하기 때문이다":"공무원은 국민의 대리인인데 사익을 따르면 위임한 국민의 신뢰가 무너지기 때문입니다.","이해충돌 회피의 기본원칙은 “누구도 자신의 사건에 대해 판결할 수 없다”는 것이다":"자기가 당사자인 사건은 이해관계 때문에 공정한 판단이 어려우므로 맡을 수 없다는 원칙입니다.","인간을 자아실현인ㆍ복잡인으로 파악한다":"신행정론은 인간을 스스로 능력을 펼치려 하며 욕구와 동기가 복합적인 존재로 봅니다.","인간의 능력부족과 환경의 불확실성에 기초한 제한된 합리성을 전제로 한다":"사람은 능력이 부족하고 환경이 불확실해 완전한 합리성이 아닌 제한된 합리성으로 결정합니다.","인간의 능력에 한계가 있으므로 최적의 대안이 아닌 만족하는 정도의 대안을 결정한다":"사람은 모든 대안을 알 수 없어 최선을 찾지 못하고 어느 정도 만족하면 결정을 멈춥니다.","인간의 욕구를 계층화한 점에서는 머슬로(A. Maslow)와 공통된 견해를 지니고 있다":"욕구를 낮은 것부터 높은 것까지 층으로 나눈 점에서 매슬로의 욕구단계론과 닮은 이론입니다.","인사관리기능을 수행하기 위해 각 부처의 인사기관과 각 지방자치단체의 인사기관이 있다":"인사 업무는 전담 중앙기관에만 있지 않고 각 부처와 지자체의 인사기관도 나눠 맡습니다.","일반적으로 정보는 공공재 성격이 강하기 때문에 행정정보의 비대칭성 문제는 해소 내지 완화되어야 하는 것이 바람직하다":"정보는 여럿이 함께 써도 줄지 않는 공공재라서 행정정보의 격차는 줄이는 방향이 맞습니다.","일반적으로 조직 내에서 행해진 비윤리적 행위이다":"조직 안에서 벌어진 윤리에 어긋나는 행위가 일반적으로 고발의 대상이 됩니다.","일선관료의 적절한 재량 부여를 강조한다":"현장에서 시민을 직접 만나는 관료는 상황이 제각각이라 재량이 있어야 집행이 맞아 갑니다.","일정기간 지역에 거주하지 않았더라도 주민등록만 되어 있다면 지방자치법상 주민으로서의 권리와 의무의 주체가 된다":"거주 기간과 관계없이 주민등록이 되어 있으면 법적으로 권리를 갖고 의무를 지는 주민이 됩니다.","입법국가에 비해 현대행정의 합법성은 상황에 따라 신축성을 부여하는 법의 적합성을 강조한다":"현대행정은 법 조문을 엄격히 따르기보다 상황에 맞게 유연하게 적용할 수 있는 법을 중시합니다.","자신이 살고 있는 지역의 지방자치단체 발전과 운영에 기여할 수 있다":"주민은 자기 지역의 지방자치단체 운영에 참여하는 방식으로 지역 발전에 힘을 보탤 수 있어요.","자치경찰사무로 지역 내 주민의 생활안전 활동과 교통활동에 관한 사무가 있다":"주민 생활과 가까운 생활안전과 교통 관련 사무를 지자체가 맡는 자치경찰의 업무 범위예요.","자치권을 인간의 자연권과 마찬가지로 본래적이고 침해할 수 없는 고유한 권리라고 본다":"자치권은 국가가 준 것이 아니라 주민이 태어날 때부터 가진 권리라는 이론입니다.","작성하고, 국회에 제출하는 예산안의 첨부서류에 이를 포함해야 한다":"세금 감면으로 포기한 세수를 따로 밝히는 문서로 예산안 첨부서류에 넣어 국회에 냅니다.","작업환경이나 물리적 조건보다 조직구성원의 사회심리적 요인을 중시한다":"조명이나 임금 같은 물리적 조건보다 소속감과 인정 같은 심리가 성과를 좌우한다고 봅니다.","재정운용의 비능률이 발견된 경우 시정을 요구할 수 있고 차년도 예산과정에서 쟁점화될 수 있다":"비능률이 드러나면 고치도록 요구하며 이 사안이 다음 해 예산 심의의 논쟁거리가 됩니다.","전자정부 발전으로 인한 정보화의 역기능은 사회적 질서와 안전을 위협하는 디지털 위험으로 진행될 수 있다":"정보화가 깊어지면 해킹과 개인정보 유출 같은 디지털 위험이 사회 안전을 흔들 수 있어요.","전자정부 서비스는 이용자들의 거래비용과 기회비용 및 민원업무 감소에 기여한다":"온라인 처리로 방문과 대기에 드는 비용과 시간이 줄고 민원 처리 업무도 줄어듭니다.","정보가 조직원들에게 공유된다":"구성원 누구나 정보를 나누며 함께 배워 조직이 스스로 개선해 나가는 구조입니다.","정보가 최고관리층에 집중된다":"정보와 결정권이 윗선에 모여 아래 구성원은 지시를 받아 수행하는 구조예요.","정부 내부의 관리보다는 외부 주체와의 관계를 강조한다":"정부가 혼자 관리하기보다 민간과 시민단체 같은 외부 주체와의 협력 관계를 중시합니다.","정부예산의 공유재적 성격 때문에 자원배분의 비효율성이 발생한다":"예산은 모두의 돈이라 아껴 쓸 동기가 약해 낭비가 생기고 자원이 비효율적으로 배분됩니다.","정부의 맞춤형 전자서비스와 빅데이터 산업 고도화 차원에서 개인정보의 행정기관 간 공동 활용은 중요하다":"기관들이 개인정보를 함께 쓰면 따로 모을 필요가 없어 맞춤형 서비스와 빅데이터 활용이 쉬워집니다.","정책결정단계에서 주된 역할을 하는 참여자와 정책내용에 초점을 맞춘다":"결정 단계에 영향력을 가진 참여자가 누구이고 어떤 내용이 채택되는지를 봅니다.","정책결정의 결과물인 정책목표를 달성해 가는 과정을 정책집행으로 이해한다":"정책집행은 이미 정해진 목표를 현실에서 하나씩 이뤄 나가는 과정이라는 시각입니다.","정책공동체에 비해 상대적으로 많은 이해관계자와 느슨한 관계를 가정한다":"참여자가 많고 관계가 느슨해 결속이 약하므로 정책공동체보다 개방적인 형태입니다.","정책대안의 선택과 가치판단은 분리하기 어려운 것으로 보며, 정책결정과정을 약간의 향상을 위해 그럭저럭 헤쳐 나가는 과정으로 본다":"기존 정책에서 조금씩만 바꾸는 방식이라 가치와 수단을 따로 떼어 최적안을 찾지 않습니다.","정책분석의 초점은 정부제도의 공식적ㆍ법적 기구에 맞추는 것이다":"정부 기관의 헌법상 지위와 법적 구조를 분석하면 정책을 이해할 수 있다고 봅니다.","정책의제화를 요구하는 집단의 규모와 영향력이 클수록 정책의제화될 가능성이 높다":"의제화를 요구하는 집단의 힘이 크면 정부가 그 요구를 무시하기 어려워집니다.","정책이 결과물을 창출하는 과정에서 정책결정자가 어떤 역할을 했는지에 관심이 있다":"정책 산출 과정에서 결정자가 맡은 역할을 중심에 두고 분석하는 연구 관점입니다.","정책이 집행된 이후에 나타나는 변화가 정책에 기인한 것인지, 다른 요인 때문인지를 밝히는 것과 관련된다":"나타난 변화가 정말 정책의 효과인지 다른 원인의 영향인지 가려내는 정도와 관련됩니다.","정책이 추구하는 목표를 분명히 하고, 정책결정자의 의도를 정확히 이해할수록 정책은 보다 효과적으로 집행될 수 있다":"목표가 분명하고 결정자의 의도가 정확히 전달되면 집행 과정의 해석 차이가 줄어듭니다.","정책집행을 다수의 참가자들 사이의 상호작용으로 이해한다":"집행을 위에서 내려오는 일방적 명령이 아니라 여러 참여자가 주고받는 협상으로 봅니다.","정책평가 결과의 일반화 가능성을 의미한다":"한 사례에서 나온 평가 결과를 다른 대상이나 상황에도 적용할 수 있는 정도입니다.","조직구성원들의 참여 확대와 창의성 발현이 요구되고 있다":"구성원의 아이디어를 끌어낼 참여 구조가 있어야 변화하는 환경에 대응할 수 있어요.","조직구성원의 보상을 통한 교환관계에서 형성된다":"상사가 성과에 맞는 보상을 주고 구성원이 그에 맞게 일하는 주고받는 관계가 바탕입니다.","조직 내부의 비리를 대외적으로 폭로하는 외부적 행위이다":"내부 사정을 아는 구성원이 조직 밖에 알린다는 점에서 외부로 향하는 행위입니다.","조직 내의 직위들을 각 직위에 배당된 직무의 속성에 따라 분류ㆍ관리하는 제도를 말한다":"사람이 아니라 직무의 특성을 기준으로 직위를 나누고 관리하는 직위분류제의 정의입니다.","조직을 환경과 상호작용하는 동태적ㆍ유기체적 개방체제로 파악한다":"조직이 환경과 자원과 정보를 주고받으며 끊임없이 변하는 살아 있는 체제로 봅니다.","조직의 분권화를 통해 조직계층의 단순화, 명령과 책임 등을 명확히 할 수 있다":"권한을 아래로 넘기면 단계가 줄어 의사결정이 빨라지고 누가 책임지는지 분명해집니다.","조직이 속한 사회의 민주화가 촉진되고 있다":"사회가 민주화될수록 조직도 구성원 의견을 수용하고 투명하게 운영해야 하는 압력을 받습니다.","주로 생리적 욕구, 안전욕구 등을 만족시키는 요인들이다":"충족돼도 만족이 커지지는 않지만 부족하면 불만이 생기는 낮은 단계의 욕구 요인입니다.","주민이 감사청구한 일정한 재무회계 사항과 관련이 있는 지방자치단체의 장 등의 위법한 행위 등에 대하여 손해를 배상하게 하는 제도이다":"주민이 감사청구를 거친 재무회계 문제에서 단체장 등의 위법 행위로 생긴 손해를 물게 하는 제도입니다.","지방자치는 지방분권을 전제로 하며, 주민참여는 ‘풀뿌리 민주주의’ 원리를 구현한다":"중앙에서 아래로가 아니라 주민이 직접 참여해 정치의 기초부터 세우는 민주주의입니다.","지방자치단체는 조직과 운영을 합리적으로 하고 규모를 적절하게 유지하여야 한다":"지자체가 몸집을 불리지 말고 효율적으로 조직을 꾸려야 한다는 책무를 규정합니다.","지방자치단체라는 공법인을 통해 주민에게 필요한 주요 정책의 실험장 역할을 한다":"지방자치단체가 새 정책을 먼저 시험해 보고 성과가 좋으면 다른 곳으로 퍼뜨릴 수 있어요.","지방자치단체에는 특별시, 광역시, 도, 특별자치도, 특별자치시와 시ㆍ군ㆍ구(자치구)가 포함된다":"광역에는 특별시와 광역시와 도 등이, 기초에는 시와 군과 자치구가 있다는 구분을 담고 있어요.","지배계층은 모든 정책과정을 장악하고 영향력을 행사하며 정책의 혜택을 누린다":"소수의 지배층이 정책 전 과정을 쥐고 흔들며 이익도 그들이 가져간다고 봅니다.","지식사회를 설계하고 지식관리를 통해 가치를 창출하고 극대화하는 것을 의미한다":"지식을 쌓고 나누며 관리해 행정의 가치를 키워 가는 방식을 가리킵니다.","지역주민이 그 지역의 제반 문제를 스스로 결정하고 처리하는 것이다":"주민이 자기 지역의 일을 외부 간섭 없이 스스로 정하고 집행하는 것이 핵심입니다.","지역특성에 맞는 행정과 정책을 통해 행정의 능률성과 책임성을 확립한다":"지역 사정에 맞게 행정하므로 낭비가 줄고 주민에게 직접 책임을 지게 됩니다.","직무관련자에게 사적으로 노무 또는 조언ㆍ자문 등을 제공하고 대가를 받는 행위를 하여서는 아니 된다":"직무와 이해관계가 있는 사람에게 사적으로 일해 주고 돈을 받으면 공정성이 의심받아 금지됩니다.","직무관련자인 소속 기관의 퇴직자(공직자가 아니게 된 날부터 2년 이내인 자)와 사적 접촉(골프, 여행, 사행성 오락을 같이 하는 행위)을 하는 경우 소속기관장에게 신고하여야 한다":"퇴직한 지 2년 이내인 직무관련자와 골프나 여행 같은 사적 접촉을 하면 소속기관장에게 알려야 합니다.","직무를 수준별로 구분해 직급과 등급을 형성하는 작업이다":"직무의 난이도와 책임 수준을 비교해 직급과 등급으로 세로 방향의 서열을 매깁니다.","직무를 종류별로 구분해 직렬과 직군을 형성하는 작업이다":"직무의 성격이 같은 것끼리 묶어 직렬과 직군으로 나누는 가로 방향의 분류예요.","직무수행 중 알게 된 비밀 또는 소속 공공기관의 미공개정보를 사적 이익을 위하여 이용하거나 제3자로 하여금 이용하게 하여서는 아니 된다":"직무 중 알게 된 비밀을 자기나 남의 이익에 쓰면 공정한 직무 수행을 해쳐 금지됩니다.","직무의 종류가 유사하고 그 책임과 곤란성의 정도가 서로 다른 직급의 군을 말한다":"하는 일은 비슷하지만 책임의 무게와 어려움이 다른 직급들을 하나로 묶은 단위입니다.","집권적 관료제가 공공서비스를 제공하는데 있어서 유일한 최선의 방안은 아니라고 한다":"중앙집권적 관료제만이 정답은 아니며 경쟁과 선택이 있는 다른 공급 방식도 가능하다고 봅니다.","집행의 영향을 받는 대상집단의 행태와 참여를 강조한다":"정책이 닿는 대상집단이 어떻게 행동하고 참여하는지가 집행 성패를 좌우한다고 봅니다.","참여ㆍ소통으로 수요자가 원하는 서비스와 정보를 제공하는 정부이다":"시민이 의견을 내고 소통하면 그에 맞춰 서비스와 정보를 제공하는 정부 형태입니다.","참여와 형평의 가치를 중심으로 현실문제의 처방적 연구를 중시한다":"현실의 사회문제를 풀 방안을 내놓는 연구를 하되 기준은 참여와 사회적 형평에 둡니다.","청년일자리 창출에 관한 조례의 필요성에 따라 요건을 갖추어 ○○시 조례의 제정을 청구하였다":"필요한 조례가 있으면 주민이 일정한 요건을 갖춰 직접 조례 제정을 청구할 수 있는 권리입니다.","카리스마적 리더십을 기반으로 한다":"지도자의 개인적 매력과 신뢰가 구성원이 따르는 힘의 바탕이 되는 리더십입니다.","특별시ㆍ광역시 또는 특별자치시가 아닌 인구 50만 이상의 시는 자치구가 아닌 구를 둘 수 있다":"인구가 많은 시는 자치구가 아닌 일반구를 두어 행정을 나눠 맡게 할 수 있습니다.","특별지방자치단체는 법인으로 한다":"독자적인 권리와 의무의 주체가 되는 법인격을 가지는 단체입니다.","특별지방자치단체의 구역은 특별한 사정이 있을 때에는 해당 지방자치단체 구역의 일부만을 구역으로 할 수 있다":"특별한 사정이 있으면 구성 단체 전체가 아니라 일부 지역만 구역으로 정할 수 있습니다.","특별지방자치단체의 의회는 규약으로 정하는 바에 따라 구성 지방자치단체의 의회 의원으로 구성한다":"규약에 정해 둔 대로 구성 지방자치단체 의회 의원들이 특별지방자치단체 의회를 이룹니다.","특정 공공업무의 처리방식을 선택하기 위한 사전 검증절차이다":"업무를 정부가 계속 맡을지 민간에 넘길지 정하기 전에 시장 경쟁에 견줘 보는 절차예요.","폐쇄적 경계를 강조하고, 배타성이 매우 강하다":"외부 참여자를 막고 내부 구성원끼리 이익을 나누는 폐쇄적 관계를 가리킵니다.","폐지되거나 기능이 이관된 기관의 예산을 신설된 기관의 예산으로 재분배하는 것":"기관이 없어지거나 기능이 옮겨질 때 그 예산을 새로 맡은 기관 몫으로 옮겨 주는 일이에요.","합리적 선택이론에 제도의 역할을 접목해서 공공부문에까지 확대 적용한다":"개인이 이익을 따져 행동한다는 경제학 가정을 제도 분석과 결합해 정부 영역까지 넓힙니다.","행정개혁을 위해 정부혁신추진위원회를 설치하였다":"개혁을 전담할 기구로 정부혁신추진위원회를 새로 두었다는 내용이에요.","행정개혁조사위원회에 의해 추진되었다":"행정개혁조사위원회라는 위원회가 개혁 작업을 주도했다는 설명입니다.","행정수반으로부터의 독립성과 다수 위원들의 협의에 의한 의사결정을 하는 합의성 등을 기준으로 유형화할 수 있다":"행정수반에서 얼마나 독립적인지, 여러 위원이 합의로 결정하는지에 따라 종류를 나눕니다.","행정안전부장관은 지방자치단체의 자치사무에 관하여 법령 위반사항에 대해서만 서류·장부 또는 회계를 감사할 수 있다":"감사 범위가 법령 위반으로 한정되어 자치사무의 당부까지는 따지지 못하도록 제한한 규정이에요.","행정절차법과 공공기관의 정보공개에 관한 법률을 제정해 행정의 투명성을 제고하고자 하였다":"행정절차법과 정보공개 관련 법을 만들어 행정이 어떻게 이뤄지는지 국민에게 드러내려 했습니다.","행정현상을 여러 변수 중에서 환경을 포함해 거시적으로 접근한다":"행정을 환경과 주고받는 하나의 체제로 보고 전체 구조 속에서 설명하려 합니다.","현대국가는 모든 자본가 계층의 공통된 이해관계를 대변하기 위한 위원회와 같다":"국가가 지배계급인 자본가 전체의 공통 이익을 관리하는 도구처럼 움직인다고 봅니다.","현재 우리나라의 중앙인사기관은 국무총리 소속의 인사혁신처이다":"국무총리 아래에 있는 인사혁신처가 지금 중앙인사기관의 역할을 하고 있습니다.","회계연도에서 국가의 수입과 지출 실적을 확정적 계수로 표시하는 행위이다":"한 회계연도에 실제로 걷고 쓴 돈을 확정된 숫자로 나타내는 행위입니다.","효과성ㆍ생산성ㆍ민주성ㆍ대응성ㆍ사회적 적실성과 종합적인 행정개혁을 중시한다":"효과성과 대응성 등 여러 가치를 목표로 삼고 행정 전반을 아우르는 개혁을 중시합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
